// Validated JS BigInt reference implementation of this build's bech32 checksum.
// Uses BigInt everywhere so Python's arbitrary-precision >> << & ^ semantics
// (including on huge AND negative integers, two's-complement-to-infinity) are
// reproduced exactly. No Uint8Array / DataView anywhere.

const GEN = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

export function bech32Polymod(values) {
  let chk = 1n;
  for (const v of values) {
    const top = chk >> 25n;
    chk = ((chk & 0x1ffffffn) << 5n) ^ v;
    for (let i = 0n; i < 5n; i++) {
      chk ^= ((top >> i) & 1n) ? GEN[Number(i)] : 0n;
    }
  }
  return chk;
}

// Python's `for x in hrp` iterates CODE POINTS, and ord() yields the full
// code point (e.g. ord('\u{1F600}') === 128512), never a surrogate half.
// Array.from / for..of on a JS string also iterates code points.
export function hrpExpand(hrp) {
  const cps = [];
  for (const ch of hrp) cps.push(BigInt(ch.codePointAt(0)));
  const out = [];
  for (const c of cps) out.push(c >> 5n);
  out.push(0n);
  for (const c of cps) out.push(c & 31n);
  return out;
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...hrpExpand(hrp), ...data]) === 1n;
}

export function bech32CreateChecksum(hrp, data) {
  const polymod =
    bech32Polymod([...hrpExpand(hrp), ...data, 0n, 0n, 0n, 0n, 0n, 0n]) ^ 1n;
  const out = [];
  for (let i = 0n; i < 6n; i++) out.push((polymod >> (5n * (5n - i))) & 31n);
  return out;
}

// Reproduces `print(list_of_ints)` then `print(bool)` from CPython.
export function render(hrp, data) {
  const checksum = bech32CreateChecksum(hrp, data);
  const combined = [...data, ...checksum];
  const isValid = bech32VerifyChecksum(hrp, combined);
  return (
    '[' + checksum.map((x) => x.toString()).join(', ') + ']\n' +
    (isValid ? 'True' : 'False') + '\n'
  );
}

